        edges.append((u, v, w, i + 1))

    def get_graph():
        return [[-1] * (m + 1) for _ in range(n + 1)]

    def build_graph_with_exclusion(excluded_indices):
        adj = [[] for _ in range(n + 1)]
        for i, (u, v, w, idx) in enumerate(edges):
            if idx not in excluded_indices:
                adj[u].append((v, i))
                adj[v].append((u, i))
        return adj

    def is_disconnected(adj):
        if s == t:
            return True
        visited = {s}
        queue = deque([s])
        while queue:
            u = queue.popleft()
            for v, _ in adj[u]:
                if v not in visited:
                    visited.add(v)
                    queue.append(v)
                    if v == t:
                        return False
        return True

    # Case 0: Remove 0 roads
    adj0 = build_graph_with_exclusion(set())
    min_cost = float('inf')
    result_edges = []

