def solution(input_string):
    lines = input_string.strip().split('\n')
    if not lines:
        return "Nicky\n"

    first_line = lines[0].strip().split()
    n = int(first_line[0])
    k = int(first_line[1])

    # Get pile sizes from second line
    a = list(map(int, lines[1].split()))

    if not a:
        return "Kevin\n"

    memo = {}

    def get_grundy(x):
        if x == 0:
            return 0

        if x in memo:
            return memo[x]

        # Option 1: remove 1 cow
        options = {get_grundy(x - 1)}

        # Option 2: if x is even, replace with k piles of x/2
        if x % 2 == 0:
            y = x // 2
            if k % 2 == 1:
                options.add(get_grundy(y))
            else:
                options.add(0)

        # Compute mex (minimum excluded non-negative integer)
        mex = 0
        while mex in options:
            mex += 1

        memo[x] = mex
        return mex

    # Compute XOR sum of all pile Grundy values
    xor_sum = 0
    for pile in a:
        xor_sum ^= get_grundy(pile)

    # Non-zero XOR sum means first player (Kevin) wins
    result = "Kevin\n" if xor_sum != 0 else "Nicky\n"
    return result

