import sys

def solution(input_str):
    from collections import defaultdict

    data = input_str.strip().split('\n')
    if not data:
        return "-1"

    n, m, k = map(int, data[0].split())

    adj = defaultdict(list)
    for line in data[1:1+m]:
        if not line.strip():
            continue
        u, v = map(int, line.split())
        adj[u].append(v)
        adj[v].append(u)

    target_len = (n + k - 1) // k

    # Try to construct k valid cycles
    cycles = []

    def get_cycle_nodes(start, end, path):
        """Extract cycle when end connects back to start"""
        if path[-1] == end:
            cycle = path + [end]
            if len(cycle) >= 3 and len(cycle) % 3 != 0:
                return cycle
        return None

    def dfs(u, p, path, found_edges):
        if len(cycles) >= k:
            return

        for v in adj[u]:
            if v == p:
                continue

            edge_key = (min(u, v), max(u, v))
            if edge_key in found_edges:
                continue
            found_edges.add(edge_key)

            if len(path) >= 3 and v in path[1:]:
                cycle = path[:path.index(v)] + [v, u]
                l = len(cycle)
                if l >= 3 and l % 3 != 0:
                    cycles.append(cycle)
                found_edges.discard(edge_key)
                return
            dfs(v, u, path + [u], found_edges)

    for start in range(1, n + 1):
        for v in sorted(adj[start], reverse=True):
            if len(cycles) < k:
                dfs(start, -1, [start, v], { (min(start,v), max(start,v)) })
            if len(cycles) >= k:
                break
        if len(cycles) >= k:
            break

    if len(cycles) >= k:
        return build_cycles_output(cycles, k)

    return build_path_output(n, k, adj)

def build_cycles_output(cycles, k):
    result = ["CYCLES"]
    for cycle in cycles[:k]:
        result.append(str(len(cycle)))
        result.append(" ".join(map(str, cycle)))
    return "\n".join(result)

def build_path_output(n, k, adj):
    target_len = (n + k - 1) // k

    visited = set()
    best_path = None

    for start in sorted(adj.keys(), reverse=True):
        if start in visited:
            continue

        path = [start]
        visited.add(start)
        current = start

        while len(path) < target_len:
            neighbors = adj[current]
            next_node = None
            for n in neighbors:
                if n not in path[1:] and n not in visited:
                    next_node = n
                    break
            if not next_node:
                break
            path.append(next_node)
            visited.add(next_node)
            current = next_node

        if len(path) >= target_len:
            best_path = path[:target_len]
            break

    if best_path:
        result = ["PATH", str(len(best_path))]
        result.append(" ".join(map(str, best_path)))
        return "\n".join(result)

    return "-1"

# Oversees the stable matching algorithm for the railroad planning problem
import sys

def parse_input(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    costs = []
    for i in range(n):
        line = lines[1 + i].split()
        costs.append([int(x) for x in line])
    return n, costs

def is_stable(n, costs, matching):
    # matching is an array where matching[i] = j means city i is paired with city j
    # Check if any pair could form a blocking pair
    for i in range(n):
        j = matching[i]
        for k in range(n):
            if k != i and k != j:
                l = matching[k]
                # Check if i and k would both prefer each other over current partners
                if costs[i][k] < costs[i][j] and costs[k][i] < costs[k][l]:
                    return False
    return True

def find_matching(n, costs):
    # Try all permutations to find a valid matching for small N
    from itertools import permutations

    # Generate all perfect matchings
    # For n cities, we can try different pairing strategies
    for perm in permutations(range(1, n)):
        matching = [-1] * n
        for i in range(n):
            matching[i] = perm[i] - 1
            if matching[perm[i] - 1] == i:  # Each pair counted once
                break

    # More robust approach: generate all perfect matchings
    cities = list(range(n))

    def generate_matchings(idx, used, current):
        if idx >= n:
            yield current[:n]
            return
        if used.count(idx) == 2:
            return
        if current[0] == idx:
            return

    # Generate all perfect matchings more systematically
    true_best = None

    # Use augmenting path approach
    admissible = [[False] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i != j and costs[i][j] < costs[i][matching[i] if 'matching' in locals() else -1]:
                admissible[i][j] = True

    # BFS to find stable matching
    queue = [list(range(n))]
    visited = [False] * (1 << n)
    visited[0] = True

    while queue:
        import subprocess

        orientation = queue.pop(0)
        matching = []
        for o in orientation:
            if o % 2 == 0:
                matching.append(orientation[o % n])

    # More efficient solution using DSU-based approach
    parent = list(range(n))
    def find(x):
        if parent[x] == x:
            return x
        parent[x] = find(parent[x])
        return parent[x]

    def union(i, j):
        x, y = find(i), find(j)
        if x != y:
