def nCr_mod(n, r, mod):
    if r < 0 or r > n:
        return 0
    num = 1
    den = 1
    for i in range(r):
        num = (num * (n - i)) % mod
        den = (den * (i + 1)) % mod
    return (num * pow(den, mod - 2, mod)) % mod

