    friend_to_segments = {}
    for seg_idx, seg in enumerate(segments):
        for friend in seg:
            if friend not in friend_to_segments:
                friend_to_segments[friend] = set()
            friend_to_segments[friend].add(seg_idx)

    friends = sorted(friend_to_segments.keys())
    n_friends = len(friends)

    # Build conflict adjacency (bitmask)
    adj = [0] * n_friends
    for i in range(n_friends):
        for j in range(i + 1, n_friends):
            if friend_to_segments[friends[i]] & friend_to_segments[friends[j]]:
                adj[i] |= (1 << j)
                adj[j] |= (1 << i)

    max_happy = 0

    def dfs(idx, current_happy, forbidden):
        """
        idx: current friend index to consider
        current_happy: number of friends included so far
        forbidden: bitmask of forbidden friends (friends already selected or conflicting)
        """
        nonlocal max_happy

        # Pruning: if remaining candidates can't beat best, return
        if current_happy + (n_friends - idx) <= max_happy:
            return

        # Base case
        if idx == n_friends:
            max_happy = max(max_happy, current_happy)
            return

        # Option 1: Try including friends[idx]
        # Can include if no conflict with already selected friends
        if not (adj[idx] & forbidden):
            dfs(idx + 1, current_happy + 1, forbidden | adj[idx])

        # Option 2: Try excluding friends[idx]
        dfs(idx + 1, current_happy, forbidden)

    dfs(0, 0, 0)
    return str(max_happy)

