        visited = set()
        queue = deque()

        for diag in current_diags:
            if diag not in goal_diags:
                a, b = diag
                queue.append((a, b))
                visited.add(diag)

        while queue:
            a, b = queue.popleft()

            for neighbor in adj[a]:
                if neighbor in adj[b] and neighbor == b:
                    continue

                nb_diag = tuple(sorted((neighbor, b))) if neighbor != a else None
                if nb_diag and nb_diag not in current_diags and nb_diag in goal_diags:
