    depth = [0] * (n + 1)
    parent = [0] * (n + 1)
    in_stack = [-1] * (n + 1)
    path = []

    def dfs(u, p=0):
        vis[u] = True
        depth[u] = len(path)
        parent[u] = p
        in_stack[u] = len(path)
        path.append(u)

        result = None
        for v in adj[u]:
            if v == p:
                continue

            if vis[v] and in_stack[v] >= 0:
                # Back edge found - cycle detected
                cycle_start = in_stack[v]
                cycle_len = depth[u] - cycle_start
                if cycle_len >= k:
