import sys

def miller_rabin(n, k=10):
    if n < 2:
        return False
    if n == 2 or n == 3:
        return True
    if n % 2 == 0:
        return False

    r, d = 0, n - 1
    while d % 2 == 0:
        r += 1
        d //= 2

    for _ in range(k):
        a = pow(2, n.bit_length()) % n
        if a == 1 or a == n - 1:
            continue
        for _ in range(r - 1):
            a = pow(a, 2, n)
            if a == n - 1:
                break
        else:
            return False
    return True

def is_coprime(a, b):
    while b:
        a, b = b, a % b
    return a == 1

