def mat_mul(A, B):
    C = [[0 for _ in range(3)] for _ in range(3)]
    for i in range(3):
        for j in range(3):
            for k in range(3):
                C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD_EXP
    return C

def mat_pow(A, n):
    result = [[0 for _ in range(3)] for _ in range(3)]
    for i in range(3):
        result[i][i] = 1
    while n:
        if n % 2 == 1:
            result = mat_mul(result, A)
        A = mat_mul(A, A)
        n //= 2
    return result

