import itertools

def solution(input_str):
    n, m, k = map(int, input_str.strip().split())
    MOD = 1000000007

    if n == 1:
        # For n=1, no array can satisfy |a1-a1|=1
        return "0\n"

    def is_good(arr):
        """Check if array is good - all consecutive absolute differences equal 1"""
        r = len(arr)
        for i in range(r):
            if abs(arr[i] - arr[(i + 1) % r]) != 1:
                return False
        return True

    def count_distinct_good(arr):
        """Count distinct good arrays that can be formed by rearranging arr"""
        seen = set()
        for perm in set(itertools.permutations(arr)):
            if is_good(list(perm)):
                seen.add(perm)
        return len(seen)

    result = 0

    def generate(arr):
        nonlocal result
        if len(arr) == n:
            good_count = count_distinct_good(arr)
            if good_count > 0 and good_count <= k:
                result = (result + 1) % MOD
            return

        for i in range(1, m + 1):
            if not arr or arr[-1] <= i:
                arr.append(i)
                generate(arr)
                arr.pop()

    generate([])
    return str(result) + '\n'

