# Precompute Fibonacci numbers up to 10^18
MAX_ULONG = 10**18
Fib = [1, 2]
while Fib[-1] <= MAX_ULONG:
    Fib.append(Fib[-1] + Fib[-2])

# Maximum index needed
MAX_IDX = len(Fib)

class DPState:
    def __init__(self):
        self.memo = {}

    def solve(self, idx, n):
        """
        Return number of ways to represent n using Fibonacci numbers from idx onwards.
        """
        key = (idx, n)
        if key in self.memo:
            return self.memo[key]

        if n == 0:
            return 1

        if idx >= len(Fib) or Fib[idx] > n:
            return 0

        # Option 1: Don't use Fib[idx]
        without = self.solve(idx + 1, n)

        # Option 2: Use Fib[idx]
        with_fib = self.solve(idx + 1, n - Fib[idx])

        result = without + with_fib
        self.memo[key] = result
        return result

