def is_bitonic(arr):
    """Check if an array is bitonic (increases then decreases)."""
    n = len(arr)
    if n <= 1:
        return True
    # Find peak position
    peak = 0
    for i in range(1, n):
        if arr[i] > arr[peak]:
            peak = i
    # Check increasing before peak
    for i in range(1, peak):
        if arr[i] >= arr[i-1]:
            continue  # increasing is OK
        else:
            return False
    # Check decreasing after peak
    for i in range(peak + 1, n):
        if arr[i] <= arr[i-1]:
            continue  # decreasing is OK
        else:
            return False
    return True

