class FenwickTree:
    def __init__(self, size):
        self.tree = [0] * (size + 1)

    def add(self, idx, delta):
        idx += 1
        while idx < len(self.tree):
            self.tree[idx] += delta
            idx += idx & (-idx)

    def query(self, idx):
        idx += 1
        s = 0
        while idx > 0:
            s += self.tree[idx]
            idx -= idx & (-idx)
        return s


