def stable_sort_table(table, col):
    """Stably sort table rows by the given column."""
    n = len(table)
    if n == 0:
        return table
    indexed = list(range(n))
    indexed.sort(key=lambda i: (table[i][col], i))
    return [list(table[i]) for i in indexed]

