from math import isqrt

def get_divisors(n):
    """Get all divisors of n > 1"""
    if n <= 1:
        return set()
    divs = set()
    for d in range(1, isqrt(n) + 1):
        if n % d == 0:
            divs.add(d)
            divs.add(n // d)
    return divs

