        # Calculate minimum cost with option to remove one subsegment

        # Option A: No removal
        cost_no_rem = 0
        possible = True
        for c in costs:
            if c == INF:
                possible = False
                break
            cost_no_rem += c

        if possible:
            ans = min(ans, cost_no_rem)

        # Option B: Remove subsegment
        # Use prefix sums with INF handling
        n = len(costs)
        prefix = [INF] * (n + 1)
        prefix[0] = 0

        for i in range(n):
            if costs[i] == INF:
                prefix[i + 1] = INF
            else:
                prefix[i + 1] = prefix[i] + costs[i]

        # Find minimum cost subsegment to remove
