        # For efficient calculation: precompute min prefix valid
        # and iterate through possible removal endpoints

        # Try removing subsegment [l, r] (0-indexed, inclusive)
        # Cost = prefix[l] + (prefix[n] - prefix[r+1]) + (r - l + 1) * a

        # Only consider removals where the result is possible
