    for _ in range(k):
        if not pq:
            break
        abs_val, idx, val = heapq.heappop(pq)

        if val == 0:
            continue

        # Greedily move element toward zero or nearest value
        if val > 0:
            # If positive: reduce to 1 or move closer to zero
            if val <= x:
                val = 1
            else:
                num_ops = (val - 1) // x
                val = val - num_ops * x
