        """Find valid set scores for pattern (pat_a : pat_b) using backtracking"""

        total_sets = pat_a + pat_b  # Number of sets played

        def backtrack(a_wins, b_wins, set_idx, a_sum, b_sum, path):
            # Check if we've completed all sets
            if set_idx == total_sets:
                if a_wins == pat_a and b_wins == pat_b:
